def choose_move(observation):
    obs = observation or {}
    env = obs.get("environment_name", "resource_collection")

    def pos(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    def sign(x):
        return 1 if x > 0 else (-1 if x < 0 else 0)

    def step_toward(a, b):
        return [sign(b[0] - a[0]), sign(b[1] - a[1])]

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    sx, sy = pos(obs.get("self_position"))
    ox, oy = pos(obs.get("opponent_position"), (sx, sy))
    self_pos = (sx, sy)
    opp_pos = (ox, oy)

    gw = obs.get("grid_width", 0) or 0
    gh = obs.get("grid_height", 0) or 0

    def clamp_move(m):
        dx = m[0] if isinstance(m, (list, tuple)) and len(m) > 0 else 0
        dy = m[1] if isinstance(m, (list, tuple)) and len(m) > 1 else 0
        return [sign(dx), sign(dy)]

    def best_of(items, target=None, avoid=None):
        best = None
        best_score = None
        for it in items or []:
            p = pos(it, None)
            if p is None:
                continue
            score = manhattan(self_pos, p)
            if target is not None:
                score += manhattan(p, target) // 2
            if avoid is not None:
                score -= manhattan(p, avoid) // 2
            if best is None or score < best_score or (score == best_score and p < best):
                best = p
                best_score = score
        return best

    if env == "pursuit_evasion":
        role = obs.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)

        corners = []
        if gw > 0 and gh > 0:
            corners = [(0, 0), (0, gh - 1), (gw - 1, 0), (gw - 1, gh - 1)]
        else:
            corners = [(-10, -10), (-10, 10), (10, -10), (10, 10)]
        target = None
        bestd = None
        for c in corners:
            d = manhattan(c, opp_pos)
            if target is None or d > bestd:
                target = c
                bestd = d
        return step_toward(self_pos, target)

    if env == "territory_control":
        targets = obs.get("unclaimed_cells") or obs.get("opponent_territory") or obs.get("neutral_cells") or []
        target = best_of(targets, avoid=opp_pos)
        if target is not None:
            return step_toward(self_pos, target)
        # fallback: pressure opponent while staying active
        if manhattan(self_pos, opp_pos) > 2:
            return step_toward(self_pos, opp_pos)
        return [1, 0] if (sx + sy) % 2 == 0 else [0, 1]

    resources = obs.get("resources") or obs.get("resource_positions") or []
    target = best_of(resources, avoid=opp_pos)
    if target is not None:
        # Deny opponent if resource is much closer to them
        if manhattan(target, opp_pos) < manhattan(target, self_pos) and manhattan(self_pos, opp_pos) > 1:
            return step_toward(self_pos, opp_pos)
        return step_toward(self_pos, target)

    # Generic fallback: chase opponent if close, otherwise move toward center if known.
    if gw > 0 and gh > 0:
        center = (gw // 2, gh // 2)
        if manhattan(self_pos, opp_pos) <= 2:
            return step_toward(self_pos, opp_pos)
        return step_toward(self_pos, center)

    return step_toward(self_pos, opp_pos)

